CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS clients (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS connections (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider text NOT NULL, account text NOT NULL, status text NOT NULL DEFAULT 'connected', secret text, scopes text[] NOT NULL DEFAULT '{}', endpoint text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,provider,account));
CREATE TABLE IF NOT EXISTS grants (client_id uuid NOT NULL REFERENCES clients(id) ON DELETE CASCADE, connection_id uuid NOT NULL REFERENCES connections(id) ON DELETE CASCADE, tool text NOT NULL, approval boolean NOT NULL DEFAULT false, PRIMARY KEY(client_id,connection_id,tool));
CREATE TABLE IF NOT EXISTS oauth_states (hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, session_hash text NOT NULL, provider text NOT NULL, verifier text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS external_tools (connection_id uuid NOT NULL REFERENCES connections(id) ON DELETE CASCADE, name text NOT NULL, description text NOT NULL, schema jsonb NOT NULL, PRIMARY KEY(connection_id,name));
CREATE TABLE IF NOT EXISTS approvals (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, client_id uuid NOT NULL REFERENCES clients(id), connection_id uuid NOT NULL REFERENCES connections(id), tool text NOT NULL, args text NOT NULL, state text NOT NULL DEFAULT 'pending', expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, client_id uuid, connection_id uuid, tool text NOT NULL, status text NOT NULL, duration_ms integer NOT NULL DEFAULT 0, request_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_owner_time ON audit(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS connections_owner ON connections(user_id);
CREATE INDEX IF NOT EXISTS approvals_owner ON approvals(user_id,state);
